item.command:
/bin/bash -lc "set -euo pipefail
repo=<SOURCE_ROOT>
prefix='repository://repository-aws-health-aware-779eb7e1bc7a/'
while IFS= read -r source; do
  rel="'${source#"$prefix"}
  path=${rel%%#*}
  span=${rel#*#L}
  end=${span#*-L}
  test -f "$repo/$path"
  test "$end" -le "$(wc -l < "$repo/$path")"
done < <(rg -o '"'repository://["'^ ]+'"' okf/infrastructure)
keys="'$(rg '"'"'^benchmark_key:'"' okf/infrastructure | sed 's/.*: //')
while IFS= read -r target; do printf '%s\\n' \""'$keys" | rg -qx "$target"; done < <(rg '"'"'^    target: '"' okf/infrastructure | sed 's/.*: //')
printf '%s\\n' 'source ranges and relationship targets resolve'
printf '%s\\n' '--- root index ---'
cat okf/index.md"

